select u.id, u.content_sha256, 'O prazo de notificação previsto no inciso II do parágrafo único do art. 281 só entra em vigor após duzentos e quarenta dias contados da publicação da lei.', '["Vigência diferida do prazo de notificação."]'::jsonb, '["Dispositivo transitório."]'::jsonb, 'A regra do prazo de notificação passou a valer depois de duzentos e quarenta dias.', '["Assertiva que torna imediata a vigência do prazo de notificação erra."]'::jsonb, '[]'::jsonb, '["Art. 281"]'::jsonb, 'under_review', 'claude'
