insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os órgãos e entidades de trânsito concederam prazo de até um ano para a adaptação dos veículos de condução de escolares e de aprendizagem às normas da faixa amarela do escolar (art. 136, III) e da identificação dos veículos de autoescola (art. 154).', '["Prazo de até um ano para adaptação.","Veículos escolares e de aprendizagem."]'::jsonb, '["Dispositivo transitório, de eficácia já esgotada."]'::jsonb, 'As vans escolares tiveram um ano para pintar a faixa amarela.', '["Assertiva que fixa em dois anos o prazo de adaptação dos veículos escolares erra: era de até um ano."]'::jsonb, '[]'::jsonb, '["Art. 136"]'::jsonb, 'under_review', 'claude'
