insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Enquanto não fossem baixadas novas normas pelo Contran, continuava em vigor o art. 92 do Regulamento do antigo Código Nacional de Trânsito, aprovado por decreto de 1968.', '["Manutenção transitória de norma do regulamento anterior."]'::jsonb, '["Dispositivo transitório."]'::jsonb, 'Norma do regulamento antigo valeu provisoriamente até nova regra do Contran.', '["Assertiva que mantém indefinidamente em vigor o regulamento antigo erra: valia só até as novas normas do Contran."]'::jsonb, '[]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
