insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os valores de multas constantes do Código podem ser corrigidos monetariamente pelo Contran, respeitado o limite da variação do IPCA no exercício anterior. Os novos valores são divulgados pelo Contran com, no mínimo, noventa dias de antecedência de sua aplicação.', '["Correção monetária pelo Contran.","Limite da variação do IPCA.","Divulgação com noventa dias de antecedência."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Mínimo de noventa dias de antecedência."]'::jsonb, 'O Contran divulga o reajuste das multas com noventa dias de antecedência.', '["Assertiva que permite reajuste das multas acima do IPCA erra."]'::jsonb, '[]'::jsonb, '["Art. 258"]'::jsonb, 'under_review', 'claude'
