insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A receita arrecadada com as multas de trânsito é aplicada exclusivamente em sinalização, engenharia de tráfego, engenharia de campo, policiamento, fiscalização, renovação de frota circulante, educação de trânsito e custeio do processo de habilitação de condutores de baixa renda. Cinco por cento do valor das multas arrecadadas é depositado mensalmente em fundo de âmbito nacional destinado à segurança e educação de trânsito. O órgão responsável publica anualmente na internet os dados sobre a receita arrecadada e sua aplicação.', '["Destinação vinculada da receita das multas.","Cinco por cento ao fundo nacional.","Transparência anual na internet."]'::jsonb, '["Destinação EXCLUSIVA às finalidades legais.","Cinco por cento ao fundo nacional de segurança e educação de trânsito."]'::jsonb, 'O município aplica a arrecadação das multas em sinalização e educação de trânsito.', '["Assertiva que permite usar a receita das multas em qualquer despesa do município erra."]'::jsonb, '[]'::jsonb, '["Art. 320-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-320' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '577e317383f24abcc22b7ac7507be26c4ecd1a9c6f48ee692039baace5270fba'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
