on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os órgãos e entidades do Sistema Nacional de Trânsito podem integrar-se para ampliar e aprimorar a fiscalização de trânsito, inclusive por meio do compartilhamento da receita arrecadada com as multas.', '["Integração entre órgãos.","Compartilhamento da receita das multas."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior."]'::jsonb, 'Município e estado dividem a receita de multas fiscalizadas em conjunto.', '["Assertiva que proíbe o compartilhamento da receita das multas entre órgãos erra."]'::jsonb, '[]'::jsonb, '["Art. 320"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-320-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '3abc60646c9cb0b41ef9841640694bcbbd5a877b7856c35917cce0a2da59f4fc'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Contran fixaria, em cento e oitenta dias, a metodologia de aferição de peso de veículos, estabelecendo percentuais de tolerância, ficando suspensa nesse período a penalidade do inciso V do art. 231 e aplicando-se a penalidade de vinte UFIR por duzentos quilogramas ou fração de excesso.', '["Prazo de cento e oitenta dias para a metodologia de pesagem.","Penalidade provisória de vinte UFIR por duzentos quilogramas."]'::jsonb, '["Dispositivo transitório; parágrafo único revogado por lei de 2023."]'::jsonb, 'A metodologia de pesagem foi definida pelo Contran depois do prazo.', '["Assertiva que mantém a penalidade provisória em UFIR como regra atual erra: o dispositivo é transitório."]'::jsonb, '[]'::jsonb, '["Art. 231"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-323' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '288039058664dd7c6741d9a68e3c66123a7bcd9124f23ec41103b7cb037e47a7'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As repartições de trânsito conservam por, no mínimo, cinco anos os documentos relativos à habilitação de condutores, ao registro e ao licenciamento de veículos e aos autos de infração de trânsito. Esses documentos podem ser gerados, tramitados, arquivados e armazenados eletronicamente, desde que assegurada a autenticidade, a fidedignidade, a confiabilidade e a segurança, sendo válidos para todos os efeitos e dispensada a guarda física. O Contran regulamenta o procedimento.', '["Guarda mínima de cinco anos.","Documentos eletrônicos válidos.","Regulamentação pelo Contran."]'::jsonb, '["Mínimo de cinco anos.","ATUALIZAÇÃO: arquivamento digital foi admitido por lei posterior."]'::jsonb, 'O Detran mantém digitalmente os autos de infração por no mínimo cinco anos.', '["Assertiva que fixa em dois anos o prazo mínimo de guarda dos documentos erra: são cinco anos."]'::jsonb, '[]'::jsonb, '["Art. 280"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-325' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c2159f6e80ddc40870e703c83b192394114c45175d49ce63643b88124bfb9592'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

