select u.id, u.content_sha256, 'A Semana Nacional de Trânsito é comemorada anualmente no período compreendido entre 18 e 25 de setembro.', '["De 18 a 25 de setembro."]'::jsonb, '["Período fixo de 18 a 25 de setembro."]'::jsonb, 'As campanhas educativas se intensificam na Semana Nacional de Trânsito.', '["Assertiva que fixa a Semana Nacional de Trânsito em outro mês erra."]'::jsonb, '[]'::jsonb, '["Art. 75"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-326' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '482722113ce90f73e1c3005c9def0d0c7fb338b3971da18422e09f6d71cb44ed'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
