insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A atuação dos integrantes do Sistema Nacional de Trânsito, no que se refere ao Plano Nacional de Redução de Mortes e Lesões no Trânsito (Pnatrans), é direcionada prioritariamente ao cumprimento da meta anual de redução do índice de mortes por grupo de habitantes, apurado por Estado e pelo Distrito Federal. O objetivo geral é, ao final de 2030, reduzir à metade, no mínimo, o índice de mortes por grupo de habitantes, em relação ao apurado em 2020.', '["Meta anual de redução do índice de mortes.","Objetivo: reduzir pela metade, ao final de 2030, o índice de 2020."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Meta: reduzir à metade até o fim de 2030, em relação a 2020."]'::jsonb, 'Os órgãos priorizam ações para reduzir mortes por grupo de habitantes.', '["Assertiva que fixa meta de redução de 10% até 2030 erra: é reduzir à metade, no mínimo."]'::jsonb, '[{"termo":"Pnatrans","significado":"Plano Nacional de Redução de Mortes e Lesões no Trânsito."}]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-326-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '930df9a35d881b9bbc111090e4259feb746ef1def1427cec41e6ab956e8c0db1'
