insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os condutores dos veículos de aluguel e de escolares, para exercerem suas atividades, devem apresentar previamente certidão negativa do registro de distribuição criminal relativamente aos crimes de homicídio, roubo, estupro e corrupção de menores, renovável a cada cinco anos, junto ao órgão responsável pela concessão ou autorização.', '["Certidão negativa criminal prévia.","Crimes específicos: homicídio, roubo, estupro e corrupção de menores.","Renovação a cada cinco anos."]'::jsonb, '["Renovação a cada cinco anos."]'::jsonb, 'O motorista de táxi apresenta a certidão negativa para exercer a atividade.', '["Assertiva que dispensa a certidão negativa para condutores de transporte escolar erra."]'::jsonb, '[]'::jsonb, '["Art. 135"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-329' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '8c47c6f023ef70870bd9992e3109bd4d70bee9b74bbbea30ebde365feec78381'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os estabelecimentos onde se executam reformas ou recuperação de veículos e os que compram, vendem ou desmontam veículos, usados ou não, são obrigados a possuir livros de registro de seu movimento de entrada e saída e de uso de placas de experiência, conforme modelos aprovados pelos órgãos de trânsito. Os livros indicam a data de entrada, os dados do proprietário ou vendedor, a data da saída ou baixa, os dados do comprador, as características do veículo e o número da placa de experiência.', '["Livros de registro obrigatórios.","Entrada, saída e placas de experiência.","Dados do proprietário, do comprador e do veículo."]'::jsonb, '["Aplica-se a oficinas e a quem compra, vende ou desmonta veículos."]'::jsonb, 'A oficina anota a entrada e a saída de cada veículo em livro próprio.', '["Assertiva que dispensa o livro de registro nos estabelecimentos que desmontam veículos erra."]'::jsonb, '[]'::jsonb, '["Art. 126"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-330' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'f281f090b2f00b986ed3bd8bd05ca4812c70a2df88f9312162109cce9fae22ca'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
