insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Contran estabeleceria, em até cento e vinte dias após a nomeação de seus membros, as disposições dos arts. 91 e 92, a serem atendidas pelos órgãos executivos de trânsito e rodoviários para exercerem suas competências. Os órgãos já existentes teriam prazo de um ano, após a edição das normas, para se adequarem; os a serem criados exerceriam suas competências em cumprimento às exigências do Contran, acompanhados pelo respectivo Cetran.', '["Cento e vinte dias para o Contran.","Um ano para adequação dos órgãos existentes."]'::jsonb, '["Dispositivo transitório."]'::jsonb, 'Os órgãos existentes tiveram um ano para se adequar às normas do Contran.', '["Assertiva que fixa em dois anos o prazo de adequação dos órgãos existentes erra: era de um ano."]'::jsonb, '[]'::jsonb, '["Art. 91"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-333' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c9a01bab3444df4e46dcf107c8cd862f1df8ec4fbdd8e6dbcabec36ea3f1f680'
