insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aplicam-se os sinais de trânsito previstos no Anexo II até a aprovação pelo Contran, no prazo de trezentos e sessenta dias da publicação da lei, após manifestação da Câmara Temática de Engenharia, de Vias e Veículos e obedecidos os padrões internacionais.', '["Anexo II vale até a aprovação pelo Contran.","Prazo de trezentos e sessenta dias."]'::jsonb, '["Dispositivo transitório."]'::jsonb, 'O Contran aprovou a sinalização oficial depois do prazo.', '["Assertiva que torna definitivo o Anexo II sem aprovação do Contran erra."]'::jsonb, '[]'::jsonb, '["Art. 87"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-336' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '1ee8012ae07ec4184549a76586b5e371b49d7b6aa89ad791454fcd6a2293a9d1'
