insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As competências dos arts. 21, XV, e 24, XXII, passaram a ser atribuídas aos órgãos ou entidades ali descritos a partir de 1º de janeiro de 2024. Até 31 de dezembro de 2023, essas competências foram exercidas pelos órgãos executivos de trânsito dos Estados e do Distrito Federal.', '["Transferência de competências em 1º de janeiro de 2024.","Regra provisória até 31 de dezembro de 2023."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Dispositivo de transição, já cumprido."]'::jsonb, 'A partir de 2024, as competências passaram aos órgãos descritos nos arts. 21 e 24.', '["Assertiva que mantém a competência dos Estados após 2023 erra."]'::jsonb, '[]'::jsonb, '["Art. 21"]'::jsonb, 'under_review', 'claude'
