select u.id, u.content_sha256, 'Ficaram revogadas as leis, decretos-leis e artigos listados no dispositivo, que tratavam do trânsito antes do Código atual.', '["Revogação das leis anteriores sobre trânsito."]'::jsonb, '["Dispositivo histórico."]'::jsonb, 'O Código substituiu o regime de trânsito anterior.', '["Assertiva que mantém em vigor o antigo Código Nacional de Trânsito erra."]'::jsonb, '[]'::jsonb, '["Art. 340"]'::jsonb, 'under_review', 'claude'
