insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Anexo I reúne as definições usadas pelo Código, como acostamento, agente da autoridade de trânsito, automóvel (até oito pessoas, exclusive o condutor), bicicleta, calçada, caminhão (peso bruto total acima de 3.500 kg), ciclomotor (até 50 cm³, 4 kW e 50 km/h), cruzamento, estacionamento, estrada (via rural não pavimentada), rodovia (via rural pavimentada), parada, ultrapassagem, sinistro de trânsito, veículo de coleção (mais de trinta anos) e os tipos de vias urbanas.', '["Definições de agentes, vias, veículos e manobras.","Automóvel: até oito pessoas, exclusive o condutor.","Ciclomotor: até 50 cm³, 4 kW e 50 km/h.","Estrada = via rural não pavimentada; rodovia = via rural pavimentada.","Estacionamento x parada.","Veículo de coleção: fabricado há mais de trinta anos."]'::jsonb, '["ATUALIZAÇÃO: o texto adota o termo \"sinistro de trânsito\" e inclui definições de agente de trânsito e veículo de coleção por leis recentes.","Parada = tempo estritamente necessário ao embarque ou desembarque; estacionamento = tempo superior.","Microônibus: até vinte passageiros; ônibus: mais de vinte."]'::jsonb, 'Parar para o passageiro descer é parada; ficar além do necessário é estacionamento.', '["Assertiva que define a estrada como via rural pavimentada erra: é via rural não pavimentada, e a rodovia é a pavimentada."]'::jsonb, '[{"termo":"Sinistro de trânsito","significado":"Evento com dano ao veículo, à carga ou a pessoas, em que ao menos uma parte está em movimento."},{"termo":"Via de trânsito rápido","significado":"Via com acessos especiais, sem interseções em nível e sem travessia de pedestres em nível."}]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'anexo-1' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '9f285e39f8258c8702daa45d770c4433d1662d72892a32c1e6b3240719d6ce6c'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

